CREATE SCHEMA IF NOT EXISTS "access_control";

CREATE SCHEMA IF NOT EXISTS "public";

CREATE TABLE "companies" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" VARCHAR(150) NOT NULL,
    "slug" VARCHAR(64) NOT NULL,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "created_by" INTEGER,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "companies_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "users" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "company_id" INTEGER,
    "username" VARCHAR(50) NOT NULL,
    "email" VARCHAR(190) NOT NULL,
    "display_name" VARCHAR(120),
    "password_hash" VARCHAR(100),
    "status" VARCHAR(16) NOT NULL DEFAULT 'pending',
    "must_change_password" BOOLEAN NOT NULL DEFAULT false,
    "last_login_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "users_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "groups" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "company_id" INTEGER NOT NULL,
    "name" VARCHAR(100) NOT NULL,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "creator_id" INTEGER,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "groups_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "group_users" (
    "group_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "group_users_pkey" PRIMARY KEY ("group_id","user_id")
);

CREATE TABLE "dashboards" (
    "id" VARCHAR(64) NOT NULL,
    "title" VARCHAR(150) NOT NULL,
    "description" TEXT,
    "company_id" INTEGER,
    "created_by" INTEGER,
    "spec" JSONB NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "dashboards_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "refresh_tokens" (
    "id" UUID NOT NULL,
    "family_id" UUID NOT NULL,
    "user_id" INTEGER NOT NULL,
    "token_hash" CHAR(64) NOT NULL,
    "issued_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "revoked_at" TIMESTAMPTZ(6),
    "revoked_reason" VARCHAR(40),
    "replaced_by" UUID,

    CONSTRAINT "refresh_tokens_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "user_tokens" (
    "id" UUID NOT NULL,
    "user_id" INTEGER NOT NULL,
    "purpose" VARCHAR(24) NOT NULL,
    "token_hash" CHAR(64) NOT NULL,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "consumed_at" TIMESTAMPTZ(6),
    "created_by" INTEGER,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "user_tokens_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "login_attempts" (
    "identifier" VARCHAR(190) NOT NULL,
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "window_started_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "locked_until" TIMESTAMPTZ(6),

    CONSTRAINT "login_attempts_pkey" PRIMARY KEY ("identifier")
);

CREATE TABLE "rbac_repairs" (
    "id" VARCHAR(64) NOT NULL,
    "applied_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "rbac_repairs_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "audit_logs" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "ts" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "event" VARCHAR(64) NOT NULL,
    "actor_id" INTEGER,
    "actor" VARCHAR(190),
    "actor_company_id" INTEGER,
    "company_id" INTEGER,
    "target_user_id" INTEGER,
    "detail" JSONB NOT NULL DEFAULT '{}',

    CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "connections" (
    "id" UUID NOT NULL,
    "company_id" INTEGER NOT NULL,
    "provider" VARCHAR(32) NOT NULL,
    "name" VARCHAR(120) NOT NULL,
    "host" VARCHAR(190) NOT NULL,
    "secret" TEXT NOT NULL,
    "secret_hint" VARCHAR(24) NOT NULL,
    "status" VARCHAR(16) NOT NULL DEFAULT 'connected',
    "last_error" TEXT,
    "last_verified_at" TIMESTAMPTZ(6),
    "created_by" INTEGER,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "general_access" VARCHAR(16) NOT NULL DEFAULT 'company',

    CONSTRAINT "connections_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "datasets" (
    "connection_id" UUID NOT NULL,
    "dataset_id" VARCHAR(190) NOT NULL,
    "name" VARCHAR(255),
    "row_count" BIGINT,
    "column_count" INTEGER,
    "selected_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "selected_by" INTEGER,

    CONSTRAINT "datasets_pkey" PRIMARY KEY ("connection_id","dataset_id")
);

CREATE TABLE "context_layer_versions" (
    "id" UUID NOT NULL,
    "connection_id" UUID NOT NULL,
    "company_id" INTEGER NOT NULL,
    "name" VARCHAR(120) NOT NULL,
    "version" INTEGER NOT NULL,
    "status" VARCHAR(16) NOT NULL DEFAULT 'draft',
    "current_step" VARCHAR(16),
    "dataset_ids" JSONB NOT NULL DEFAULT '[]',
    "based_on_id" UUID,
    "session_id" TEXT,
    "extraction_mode" VARCHAR(16),
    "extraction_report" TEXT,
    "extracted_at" TIMESTAMPTZ(6),
    "object_count" INTEGER NOT NULL DEFAULT 0,
    "stats" JSONB NOT NULL DEFAULT '{}',
    "snapshot" JSONB NOT NULL DEFAULT '[]',
    "notify_team" BOOLEAN NOT NULL DEFAULT false,
    "created_by" INTEGER,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "published_by" INTEGER,
    "published_at" TIMESTAMPTZ(6),
    "datasets" JSONB NOT NULL DEFAULT '[]',
    "extraction_dataset_ids" JSONB,

    CONSTRAINT "context_layer_versions_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "context_object_reviews" (
    "object_id" UUID NOT NULL,
    "connection_id" UUID NOT NULL,
    "status" VARCHAR(16) NOT NULL,
    "note" TEXT,
    "reviewed_by" INTEGER,
    "reviewed_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "edited" BOOLEAN NOT NULL DEFAULT false,

    CONSTRAINT "context_object_reviews_pkey" PRIMARY KEY ("object_id")
);

CREATE TABLE "context_profiles" (
    "id" UUID NOT NULL,
    "connection_id" UUID NOT NULL,
    "company_id" INTEGER NOT NULL,
    "name" VARCHAR(120) NOT NULL,
    "description" TEXT,
    "created_by" INTEGER,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "context_profiles_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "context_publications" (
    "id" UUID NOT NULL,
    "connection_id" UUID NOT NULL,
    "company_id" INTEGER NOT NULL,
    "name" VARCHAR(120) NOT NULL,
    "version" INTEGER NOT NULL,
    "session_id" TEXT,
    "object_count" INTEGER NOT NULL DEFAULT 0,
    "stats" JSONB NOT NULL DEFAULT '{}',
    "snapshot" JSONB NOT NULL DEFAULT '[]',
    "notify_team" BOOLEAN NOT NULL DEFAULT false,
    "published_by" INTEGER,
    "published_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "context_publications_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "access_control"."features" (
    "id" UUID NOT NULL,
    "key" VARCHAR(64) NOT NULL,
    "label" VARCHAR(120) NOT NULL,
    "description" TEXT,
    "locked" BOOLEAN NOT NULL DEFAULT false,
    "covers" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    "sort_order" INTEGER NOT NULL DEFAULT 0,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "features_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "access_control"."permissions" (
    "id" UUID NOT NULL,
    "key" VARCHAR(100) NOT NULL,
    "label" VARCHAR(120) NOT NULL,
    "description" TEXT,
    "feature_id" UUID,
    "platform_only" BOOLEAN NOT NULL DEFAULT false,
    "admin_only" BOOLEAN NOT NULL DEFAULT false,
    "sort_order" INTEGER NOT NULL DEFAULT 0,
    "defaults_applied_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "permissions_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "access_control"."access_levels" (
    "id" UUID NOT NULL,
    "resource" VARCHAR(16) NOT NULL,
    "key" VARCHAR(16) NOT NULL,
    "rank" INTEGER NOT NULL,
    "label" VARCHAR(60) NOT NULL,
    "description" TEXT,

    CONSTRAINT "access_levels_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "access_control"."roles" (
    "id" UUID NOT NULL,
    "company_id" INTEGER,
    "kind" VARCHAR(16) NOT NULL,
    "tier" VARCHAR(16) NOT NULL,
    "name" VARCHAR(50) NOT NULL,
    "description" VARCHAR(255),
    "created_by" INTEGER,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "modified_by" INTEGER,
    "modified_at" TIMESTAMPTZ(6),

    CONSTRAINT "roles_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "access_control"."role_permissions" (
    "role_id" UUID NOT NULL,
    "permission_ids" UUID[] NOT NULL DEFAULT ARRAY[]::UUID[],
    "updated_by" INTEGER,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "role_permissions_pkey" PRIMARY KEY ("role_id")
);

CREATE TABLE "access_control"."company_features" (
    "company_id" INTEGER NOT NULL,
    "feature_ids" UUID[] NOT NULL DEFAULT ARRAY[]::UUID[],
    "updated_by" INTEGER,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "company_features_pkey" PRIMARY KEY ("company_id")
);

CREATE TABLE "access_control"."user_roles" (
    "user_id" INTEGER NOT NULL,
    "role_id" UUID NOT NULL,
    "assigned_by" INTEGER,
    "assigned_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "user_roles_pkey" PRIMARY KEY ("user_id")
);

CREATE TABLE "access_control"."user_permissions" (
    "user_id" INTEGER NOT NULL,
    "permission_ids" UUID[] NOT NULL DEFAULT ARRAY[]::UUID[],
    "updated_by" INTEGER,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "user_permissions_pkey" PRIMARY KEY ("user_id")
);

CREATE TABLE "access_control"."user_data_scopes" (
    "user_id" INTEGER NOT NULL,
    "scopes" JSONB NOT NULL DEFAULT '{}',
    "updated_by" INTEGER,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "user_data_scopes_pkey" PRIMARY KEY ("user_id")
);

CREATE TABLE "access_control"."company_dashboards" (
    "company_id" INTEGER NOT NULL,
    "dashboard_id" VARCHAR(64) NOT NULL,
    "assigned_by" INTEGER,
    "assigned_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "company_dashboards_pkey" PRIMARY KEY ("company_id","dashboard_id")
);

CREATE TABLE "access_control"."dashboard_user_access" (
    "user_id" INTEGER NOT NULL,
    "dashboard_id" VARCHAR(64) NOT NULL,
    "access_level_id" UUID NOT NULL,
    "granted_by" INTEGER,
    "granted_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "dashboard_user_access_pkey" PRIMARY KEY ("user_id","dashboard_id")
);

CREATE TABLE "access_control"."dashboard_group_access" (
    "group_id" INTEGER NOT NULL,
    "dashboard_id" VARCHAR(64) NOT NULL,
    "access_level_id" UUID NOT NULL,
    "granted_by" INTEGER,
    "granted_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "dashboard_group_access_pkey" PRIMARY KEY ("group_id","dashboard_id")
);

CREATE TABLE "access_control"."context_user_access" (
    "connection_id" UUID NOT NULL,
    "user_id" INTEGER NOT NULL,
    "access_level_id" UUID NOT NULL,
    "granted_by" INTEGER,
    "granted_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "context_user_access_pkey" PRIMARY KEY ("connection_id","user_id")
);

CREATE TABLE "access_control"."context_group_access" (
    "connection_id" UUID NOT NULL,
    "group_id" INTEGER NOT NULL,
    "access_level_id" UUID NOT NULL,
    "granted_by" INTEGER,
    "granted_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "context_group_access_pkey" PRIMARY KEY ("connection_id","group_id")
);

